# -----------------------------------------------------------------------------
# Data utilities
# -----------------------------------------------------------------------------

def norm(value: object) -> str:
    return re.sub(r"[^a-z0-9]", "", str(value).strip().lower())


def find_col(df: pd.DataFrame, aliases: list[str], contains: bool = False) -> str | None:
    lookup = {norm(c): c for c in df.columns}
    for a in aliases:
        key = norm(a)
        if key in lookup:
            return lookup[key]
    if contains:
        keys = [norm(a) for a in aliases]
        for col in df.columns:
            ckey = norm(col)
            if any(k and (k in ckey or ckey in k) for k in keys):
                return col
    return None


def to_amount(s: pd.Series | Any) -> pd.Series:
    if not isinstance(s, pd.Series):
        return pd.Series(dtype=float)
    if pd.api.types.is_numeric_dtype(s):
        return pd.to_numeric(s, errors="coerce").fillna(0.0)
    cleaned = (
        s.astype(str)
        .str.replace(",", "", regex=False)
        .str.replace(r"[^0-9.\-]", "", regex=True)
        .replace({"": np.nan, "-": np.nan, ".": np.nan})
    )
    return pd.to_numeric(cleaned, errors="coerce").fillna(0.0)


def to_dates(s: pd.Series | Any) -> pd.Series:
    if not isinstance(s, pd.Series):
        return pd.Series(dtype="datetime64[ns]")
    return pd.to_datetime(s, errors="coerce", dayfirst=True)


def read_workbook(file_bytes: bytes) -> dict[str, pd.DataFrame]:
    xls = pd.ExcelFile(BytesIO(file_bytes))
    return {sheet: pd.read_excel(xls, sheet_name=sheet) for sheet in xls.sheet_names}


def get_sheet(sheets: dict[str, pd.DataFrame], aliases: list[str]) -> tuple[str | None, pd.DataFrame | None]:
    by_norm = {norm(k): k for k in sheets}
    for alias in aliases:
        key = norm(alias)
        if key in by_norm:
            name = by_norm[key]
            return name, sheets[name].copy()
    return None, None


def choose_jobs_sheet(sheets: dict[str, pd.DataFrame]) -> tuple[str, pd.DataFrame]:
    candidates: list[tuple[str, pd.DataFrame, int]] = []
    for name, df in sheets.items():
        jid = find_col(df, ["Job_ID", "Job ID"])
        if not jid:
            continue
        score = 1
        if find_col(df, ["Quoted_Amount_KES", "Quoted Amount", "Quoted_Amount", "Quote"]):
            score += 3
        if find_col(df, ["Deposit", "Balance Rec", "Total_Amount_Received_KES"]):
            score += 3
        if find_col(df, ["Service_Type", "Job Type", "Service"]):
            score += 2
        candidates.append((name, df, score))
    if not candidates:
        raise ValueError("No sheet with a Job_ID column was found. The main job sheet must contain Job_ID.")
    for name, df, _ in candidates:
        if norm(name) == "customers" and find_col(df, ["Quoted_Amount_KES", "Quoted Amount", "Deposit", "Balance Rec"]):
            return name, df.copy()
    for name, df, _ in candidates:
        if norm(name) == "jobs":
            return name, df.copy()
    name, df, _ = sorted(candidates, key=lambda x: x[2], reverse=True)[0]
    return name, df.copy()


def clean_job_rows(raw: pd.DataFrame) -> tuple[pd.DataFrame, dict[str, int]]:
    df = raw.copy()
    before = len(df)
    df = df.drop_duplicates().copy()
    exact_duplicates = before - len(df)
    job_id_col = find_col(df, ["Job_ID", "Job ID"])
    if not job_id_col:
        raise ValueError("The selected job sheet does not contain Job_ID.")
    df[job_id_col] = df[job_id_col].astype(str).str.strip()
    duplicated_ids = df[df.duplicated(job_id_col, keep=False)][job_id_col].unique().tolist()
    conflicting_ids = []
    for jid in duplicated_ids:
        rows = df.loc[df[job_id_col] == jid].drop(columns=[job_id_col])
        if len(rows.drop_duplicates()) > 1:
            conflicting_ids.append(jid)
    conflict_count = len(conflicting_ids)
    if conflicting_ids:
        df = df.loc[~df[job_id_col].isin(conflicting_ids)].copy()
    df = df.drop_duplicates(subset=[job_id_col], keep="first").copy()
    return df, {
        "raw_rows": before,
        "exact_duplicates_removed": exact_duplicates,
        "conflicting_job_ids_excluded": conflict_count,
        "valid_jobs": len(df),
    }


def standardise_service(value: object) -> str:
    raw = str(value).strip()
    key = norm(raw)
    if not key or key in {"nan", "none", "unknown"}:
        return "Unspecified service"
    mappings = [
        (("institution", "church", "mosque", "temple", "school", "hospital"), "Institutional cleaning"),
        (("postconstruction", "postbuild", "afterconstruction"), "Post-construction cleaning"),
        (("deephouse", "housecleaning", "deepcleaning"), "Deep house cleaning"),
        (("sofa", "upholstery"), "Sofa cleaning"),
        (("carpet",), "Carpet cleaning"),
        (("fumigation", "pestcontrol"), "Fumigation"),
        (("laundry",), "Laundry cleaning"),
        (("mattress",), "Mattress cleaning"),
        (("carclean", "vehicleclean", "autoclean"), "Car cleaning"),
        (("commercial", "officeclean"), "Commercial cleaning"),
    ]
    for tokens, label in mappings:
        if any(token in key for token in tokens):
            return label
    return raw[:1].upper() + raw[1:]


def aggregate_sheet_cost(
    sheets: dict[str, pd.DataFrame],
    sheet_aliases: list[str],
    amount_aliases: list[str],
) -> tuple[pd.Series, str | None, str | None]:
    sheet_name, frame = get_sheet(sheets, sheet_aliases)
    if frame is None:
        return pd.Series(dtype=float), None, None
    jid = find_col(frame, ["Job_ID", "Job ID"])
    amount = find_col(frame, amount_aliases, contains=True)
    if not jid or not amount:
        return pd.Series(dtype=float), sheet_name, None
    frame["_job_id"] = frame[jid].astype(str).str.strip()
    frame["_amount"] = to_amount(frame[amount])
    grouped = frame.groupby("_job_id")["_amount"].sum()
    grouped.name = "Cost"
    return grouped, sheet_name, amount


def load_business_model(sheets: dict[str, pd.DataFrame]) -> tuple[pd.DataFrame, dict[str, Any]]:
    jobs_sheet, raw_jobs = choose_jobs_sheet(sheets)
    jobs, quality = clean_job_rows(raw_jobs)

    id_col = find_col(jobs, ["Job_ID", "Job ID"])
    service_col = find_col(jobs, ["Service_Type", "Service Type", "Approximate Service_Type", "Approximate Service Type", "Approx Service Type", "Job Type", "Service"], contains=True)
    quote_col = find_col(jobs, ["Quoted_Amount_KES", "Quoted Amount KES", "Quoted Amount", "Quoted_Amount", "Quote"])
    job_date_col = find_col(jobs, ["Job_Date", "Job Date", "Date"])
    completion_col = find_col(jobs, ["Completion_Date", "Completion Date", "Completion"])
    booking_col = find_col(jobs, ["Booking_Date", "Booking Date"])
    collection_date_col = find_col(jobs, ["Collection_Date", "Collection Date", "Last_Payment_Date", "Payment_Date", "Payment Date"])
    deposit_col = find_col(jobs, ["Deposit", "Deposit_KES", "Deposit Amount", "Deposit_Amount", "Deposit_Received_KES"])
    balance_col = find_col(jobs, ["Balance Rec", "Balance_Rec", "Balance_Received", "Balance Received", "Balance_Received_KES", "Balance Received KES"])
    total_col = find_col(jobs, ["Total_Amount_Received_KES", "Total Amount Received", "Amount Collected", "Total Collected"])
    outstanding_col = find_col(jobs, ["Outstanding", "Outstanding_Balance_KES", "Outstanding Balance", "Balance Outstanding"])
    collection_status_col = find_col(jobs, ["Collection_Outcome", "Collection Outcome", "Collection Status", "Collection"])
    status_col = find_col(jobs, ["Job_Status", "Job Status", "Status"])
    customer_type_col = find_col(jobs, ["Customer_Type", "Customer Type", "Client Type"])
    customer_name_col = find_col(jobs, ["Customer_Name", "Customer Name", "Customer"])
    location_col = find_col(jobs, ["Customer_Location", "Customer Location", "Customer Location Name", "Location"], contains=True)

    out = pd.DataFrame(index=jobs.index)
    out["Job_ID"] = jobs[id_col].astype(str).str.strip()
    out["Service"] = jobs[service_col].map(standardise_service) if service_col else "Unspecified service"
    out["Job_Date"] = to_dates(jobs[job_date_col]) if job_date_col else pd.NaT
    out["Completion_Date"] = to_dates(jobs[completion_col]) if completion_col else pd.NaT
    out["Booking_Date"] = to_dates(jobs[booking_col]) if booking_col else pd.NaT
    out["Date"] = out["Job_Date"].fillna(out["Completion_Date"]).fillna(out["Booking_Date"])
    if quote_col:
        out["Quoted"] = to_amount(jobs[quote_col])
    else:
        out["Quoted"] = 0.0

    # Optional transaction-level and job-level collection sheets. The user's
    # simplified workbook may have consolidated deposit/balance fields in the
    # main job sheet, while older workbooks may retain Payments/Job_Collections.
    payments_name, payments_frame = get_sheet(sheets, ["Payments", "Payment Transactions"])
    collection_name, collection_frame = get_sheet(sheets, ["Job_Collections", "Job Collections", "Collections"])
    payment_transactions = pd.DataFrame(columns=["Job_ID", "Date", "Amount", "Payment_Method"])
    payment_by_job = pd.Series(dtype=float)
    if payments_frame is not None:
        p_jid = find_col(payments_frame, ["Job_ID", "Job ID"])
        p_date = find_col(payments_frame, ["Payment_Date", "Payment Date", "Collection_Date", "Date"])
        p_amount = find_col(payments_frame, ["Received_Amount_KES", "Received Amount KES", "Amount Received", "Amount Collected", "Amount"])
        p_method = find_col(payments_frame, ["Payment_Method", "Payment Method", "Method"])
        if p_jid and p_date and p_amount:
            payment_transactions = pd.DataFrame({
                "Job_ID": payments_frame[p_jid].astype(str).str.strip(),
                "Date": to_dates(payments_frame[p_date]),
                "Amount": to_amount(payments_frame[p_amount]),
                "Payment_Method": payments_frame[p_method].astype(str) if p_method else "Not recorded",
            })
            payment_transactions = payment_transactions.dropna(subset=["Date"])
            payment_transactions = payment_transactions[payment_transactions["Amount"] > 0].copy()
            payment_by_job = payment_transactions.groupby("Job_ID")["Amount"].sum()

    collection_lookup = pd.DataFrame()
    if collection_frame is not None:
        c_jid = find_col(collection_frame, ["Job_ID", "Job ID"])
        c_total = find_col(collection_frame, ["Total_Amount_Received_KES", "Total Amount Received KES", "Amount Collected"])
        c_outstanding = find_col(collection_frame, ["Outstanding_Balance_KES", "Outstanding Balance", "Outstanding"])
        c_outcome = find_col(collection_frame, ["Collection_Outcome", "Collection Outcome", "Collection Status"])
        if c_jid:
            collection_lookup = pd.DataFrame({"Job_ID": collection_frame[c_jid].astype(str).str.strip()})
            if c_total:
                collection_lookup["_total_received"] = to_amount(collection_frame[c_total])
            if c_outstanding:
                collection_lookup["_outstanding"] = to_amount(collection_frame[c_outstanding]).abs()
            if c_outcome:
                collection_lookup["_outcome"] = collection_frame[c_outcome].astype(str)
            collection_lookup = collection_lookup.drop_duplicates("Job_ID").set_index("Job_ID")

    if total_col:
        out["Collected"] = to_amount(jobs[total_col])
        collection_amount_basis = total_col
    elif deposit_col or balance_col:
        deposit = to_amount(jobs[deposit_col]) if deposit_col else pd.Series(0.0, index=jobs.index)
        balance = to_amount(jobs[balance_col]) if balance_col else pd.Series(0.0, index=jobs.index)
        out["Collected"] = deposit + balance
        collection_amount_basis = " + ".join([c for c in [deposit_col, balance_col] if c])
    elif not collection_lookup.empty and "_total_received" in collection_lookup.columns:
        out["Collected"] = out["Job_ID"].map(collection_lookup["_total_received"]).fillna(0.0)
        collection_amount_basis = f"{collection_name}.Total_Amount_Received"
    elif not payment_by_job.empty:
        out["Collected"] = out["Job_ID"].map(payment_by_job).fillna(0.0)
        collection_amount_basis = f"{payments_name}.Received_Amount_KES grouped by Job_ID"
    else:
        out["Collected"] = 0.0
        collection_amount_basis = "No collection amount field found"

    if outstanding_col:
        # The supplied sheet uses negative signs for some customer balances.
        out["Outstanding"] = to_amount(jobs[outstanding_col]).abs()
    elif not collection_lookup.empty and "_outstanding" in collection_lookup.columns:
        out["Outstanding"] = out["Job_ID"].map(collection_lookup["_outstanding"]).fillna(0.0)
    else:
        out["Outstanding"] = (out["Quoted"] - out["Collected"]).clip(lower=0)

    if collection_status_col:
        raw_outcome = jobs[collection_status_col].fillna("").astype(str).str.lower()
        outcome = []
        for i, raw in raw_outcome.items():
            if "partial" in raw or "part" in raw:
                outcome.append("Partially paid")
            elif "unpaid" in raw or "no balance" in raw or "fully paid" in raw or "paid in full" in raw:
                if "no balance" in raw or "fully paid" in raw or "paid in full" in raw:
                    outcome.append("Paid in full")
                else:
                    outcome.append("Unpaid")
            elif "customer" in raw or "outstanding" in raw or "balance" in raw:
                outcome.append("Partially paid")
            else:
                amount = out.at[i, "Collected"]
                quote = out.at[i, "Quoted"]
                outcome.append("Paid in full" if quote > 0 and amount >= quote else ("Partially paid" if amount > 0 else "Unpaid"))
        out["Collection_Outcome"] = outcome
    elif not collection_lookup.empty and "_outcome" in collection_lookup.columns:
        raw_outcome = out["Job_ID"].map(collection_lookup["_outcome"]).fillna("").astype(str).str.lower()
        out["Collection_Outcome"] = np.select(
            [raw_outcome.str.contains("partial"), raw_outcome.str.contains("full|no balance"), raw_outcome.str.contains("unpaid")],
            ["Partially paid", "Paid in full", "Unpaid"],
            default=np.where(out["Collected"].ge(out["Quoted"]) & out["Quoted"].gt(0), "Paid in full", np.where(out["Collected"].gt(0), "Partially paid", "Unpaid"))
        )
    else:
        out["Collection_Outcome"] = np.select(
            [out["Quoted"].gt(0) & out["Collected"].ge(out["Quoted"]), out["Collected"].gt(0)],
            ["Paid in full", "Partially paid"], default="Unpaid"
        )

    out["Job_Status"] = jobs[status_col].fillna("Unknown").astype(str) if status_col else "Unknown"
    out["Customer_Type"] = jobs[customer_type_col].fillna("Unspecified").astype(str) if customer_type_col else "Unspecified"
    out["Customer_Name"] = jobs[customer_name_col].fillna("Unspecified").astype(str) if customer_name_col else "Unspecified"
    out["Location"] = jobs[location_col].fillna("Unspecified").astype(str) if location_col else "Unspecified"

    # Costs are aggregated to one row per job before merging to avoid fact-table fanout.
    labour, labour_sheet, labour_field = aggregate_sheet_cost(
        sheets, ["Labour_Payments", "Labour Payments"],
        ["Agreed_Labour_Amount_KES", "Agreed Labour Amount KES", "Agreed Labour", "Payment_Amount_KES", "Amount"]
    )
    materials, material_sheet, material_field = aggregate_sheet_cost(
        sheets, ["Material_Usage", "Materials_Usage", "Material Usage"],
        ["Material_Cost_KES", "Material Cost KES", "Cost", "Amount"]
    )
    staff_sheet, staff_frame = get_sheet(
        sheets, ["Lunch and transport", "Lunch & transport", "Lunch_Transport", "Staff_Lunch_and_Commute", "Staff Lunch and Commute"]
    )
    staff = pd.Series(dtype=float)
    staff_field = None
    if staff_frame is not None:
        staff_jid = find_col(staff_frame, ["Job_ID", "Job ID"])
        staff_total = find_col(staff_frame, ["Total_Staff_Expense_KES", "Total Staff Expense KES", "Total Staff Expense", "Expense_Amount", "Expense Amount", "Amount", "Cost"])
        if staff_jid and staff_total:
            temp_staff = staff_frame.copy()
            temp_staff["_job_id"] = temp_staff[staff_jid].astype(str).str.strip()
            temp_staff["_amount"] = to_amount(temp_staff[staff_total])
            staff = temp_staff.groupby("_job_id")["_amount"].sum()
            staff_field = staff_total
        elif staff_jid:
            # If there is no precomputed staff total, add the separate lunch and
            # commute components. This branch avoids omitting fare columns.
            lunch_col = find_col(staff_frame, ["Lunch_Expense_KES", "Lunch Expense KES"])
            total_commute_col = find_col(staff_frame, ["Total_Home_Commute_Fare_KES", "Total Home Commute Fare KES"])
            if total_commute_col:
                commute_cols = [total_commute_col]
            else:
                commute_cols = [
                    find_col(staff_frame, ["Home_to_Job_Fare_KES", "Home to Job Fare KES"]),
                    find_col(staff_frame, ["Job_to_Home_Fare_KES", "Job to Home Fare KES"]),
                ]
            component_cols = list(dict.fromkeys(c for c in [lunch_col, *commute_cols] if c))
            if component_cols:
                temp_staff = staff_frame.copy()
                temp_staff["_job_id"] = temp_staff[staff_jid].astype(str).str.strip()
                temp_staff["_amount"] = sum((to_amount(temp_staff[c]) for c in component_cols), start=pd.Series(0.0, index=temp_staff.index))
                staff = temp_staff.groupby("_job_id")["_amount"].sum()
                staff_field = " + ".join(component_cols)

    out["Labour_Cost"] = out["Job_ID"].map(labour).fillna(0.0)
    out["Material_Cost"] = out["Job_ID"].map(materials).fillna(0.0)
    out["Staff_Support_Cost"] = out["Job_ID"].map(staff).fillna(0.0)
    out["Direct_Cost"] = out[["Labour_Cost", "Material_Cost", "Staff_Support_Cost"]].sum(axis=1)
    out["Contribution"] = out["Quoted"] - out["Direct_Cost"]
    out["Margin"] = np.where(out["Quoted"].gt(0), out["Contribution"] / out["Quoted"], np.nan)

    # For collection month, prefer a real collection/payment date; otherwise use completion date.
    if collection_date_col:
        collection_dates = to_dates(jobs[collection_date_col])
        date_basis = f"Actual recorded collection/payment date: {collection_date_col}"
        date_is_proxy = False
    elif completion_col:
        collection_dates = to_dates(jobs[completion_col])
        date_basis = f"Completion date proxy: {completion_col}"
        date_is_proxy = True
    elif job_date_col:
        collection_dates = to_dates(jobs[job_date_col])
        date_basis = f"Job date proxy: {job_date_col}"
        date_is_proxy = True
    elif booking_col:
        collection_dates = to_dates(jobs[booking_col])
        date_basis = f"Booking date proxy: {booking_col}"
        date_is_proxy = True
    else:
        collection_dates = pd.Series(pd.NaT, index=jobs.index)
        date_basis = "No collection date available"
        date_is_proxy = True
    out["Collection_Date"] = collection_dates

    # Keep transaction dates where they exist. Otherwise construct a job-level
    # monthly proxy from deposit + balance received and the available job date.
    if not payment_transactions.empty:
        collection_transactions = payment_transactions.copy()
        collection_date_basis = f"Actual transaction dates from {payments_name}.{p_date}"
        collection_date_proxy = False
    else:
        collection_transactions = pd.DataFrame({
            "Job_ID": out["Job_ID"], "Date": collection_dates, "Amount": out["Collected"],
            "Payment_Method": "Not recorded"
        })
        collection_transactions = collection_transactions.dropna(subset=["Date"])
        collection_date_basis = (
            f"Job-level collection timing proxy using {collection_date_col}" if collection_date_col
            else (f"Completion/job date proxy using {completion_col or job_date_col or booking_col}" if (completion_col or job_date_col or booking_col) else "No collection date available")
        )
        collection_date_proxy = not bool(collection_date_col)

    # General business expenditure is kept separate from direct job costs.
    overhead_name, overhead_frame = get_sheet(sheets, ["General Business Expenditure", "General_Business_Expenditure", "Business Expenditure", "Uniform_Purchases"])
    overhead_total = 0.0
    overhead_by_type = pd.DataFrame(columns=["Expense Type", "Amount"])
    overhead_field = None
    if overhead_frame is not None:
        exp_amount = find_col(overhead_frame, ["Cost", "Amount", "Total_Cost", "Total_Amount", "Expense_Amount"], contains=True)
        exp_type = find_col(overhead_frame, ["Type", "Expense_Type", "Cost_Type", "Cost Treatment"])
        if exp_amount:
            overhead_frame["_Amount"] = to_amount(overhead_frame[exp_amount])
            overhead_total = float(overhead_frame["_Amount"].sum())
            overhead_field = exp_amount
            if exp_type:
                overhead_by_type = overhead_frame.groupby(exp_type, dropna=False)["_Amount"].sum().reset_index()
                overhead_by_type.columns = ["Expense Type", "Amount"]

    meta = {
        "jobs_sheet": jobs_sheet,
        "quality": quality,
        "quote_field": quote_col,
        "collection_amount_basis": collection_amount_basis,
        "collection_date_basis": collection_date_basis,
        "collection_date_proxy": collection_date_proxy,
        "collection_transactions": collection_transactions,
        "payments_sheet": payments_name,
        "labour_sheet": labour_sheet,
        "labour_field": labour_field,
        "material_sheet": material_sheet,
        "material_field": material_field,
        "staff_sheet": staff_sheet,
        "staff_field": staff_field,
        "overhead_sheet": overhead_name,
        "overhead_field": overhead_field,
        "overhead_total": overhead_total,
        "overhead_by_type": overhead_by_type,
        "has_labour": labour_sheet is not None,
        "has_materials": material_sheet is not None,
        "has_staff": staff_sheet is not None,
    }
    return out.reset_index(drop=True), meta


def money(value: float) -> str:
    value = 0.0 if pd.isna(value) else float(value)
    if abs(value) >= 1_000_000:
        return f"KES {value / 1_000_000:,.2f}M"
    if abs(value) >= 1_000:
        return f"KES {value:,.0f}"
    return f"KES {value:,.2f}"


def pct(value: float) -> str:
    return "—" if pd.isna(value) else f"{value:.1%}"


def section(title: str, subtitle: str | None = None) -> None:
    st.markdown(f"<div class='ag-section'>{title}</div>", unsafe_allow_html=True)
    if subtitle:
        st.markdown(f"<div class='ag-subtitle'>{subtitle}</div>", unsafe_allow_html=True)


def chart_layout(fig: go.Figure, height: int = 360) -> go.Figure:
    fig.update_layout(
        template="plotly_white", height=height,
        margin=dict(l=12, r=18, t=38, b=12),
        paper_bgcolor="rgba(255,255,255,0)", plot_bgcolor="rgba(255,255,255,0)",
        font=dict(family="Segoe UI, Arial, sans-serif", color=NAVY, size=12),
        legend=dict(orientation="h", yanchor="bottom", y=1.02, x=0),
        hoverlabel=dict(bgcolor="white", font_color=NAVY),
    )
    fig.update_xaxes(showgrid=True, gridcolor=GRID, zerolinecolor=GRID)
    fig.update_yaxes(showgrid=True, gridcolor=GRID, zerolinecolor=GRID)
    return fig


def apply_global_filters(jobs: pd.DataFrame) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Power BI-style Year, Month, Service Type and Location slicers.

    Year values are converted to strings so the selectbox does not mix the
    string sentinel "All" with NumPy integer values. All four filters are
    always rendered, even where a source column has only one available value.
    """
    filtered = jobs.copy()
    date_values = pd.to_datetime(filtered.get("Date", pd.Series(pd.NaT, index=filtered.index)), errors="coerce")
    year_values = sorted(
        [str(int(v)) for v in date_values.dropna().dt.year.unique().tolist()],
        reverse=True,
    )
    month_names = [
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December",
    ]
    service_series = filtered.get("Service", pd.Series("Unspecified service", index=filtered.index))
    location_series = filtered.get("Location", pd.Series("Unspecified", index=filtered.index))
    service_values = sorted({str(v).strip() for v in service_series.dropna().tolist() if str(v).strip()})
    location_values = sorted({str(v).strip() for v in location_series.dropna().tolist() if str(v).strip()})

    with st.sidebar:
        st.markdown("<div class='ag-filter-heading'>FILTERS</div>", unsafe_allow_html=True)
        st.markdown("<div class='ag-filter-heading'>YEAR</div>", unsafe_allow_html=True)
        selected_year = st.selectbox(
            "Year", ["All"] + year_values, index=0,
            label_visibility="collapsed", key="ag_filter_year",
        )
        st.markdown("<div class='ag-filter-heading'>MONTH</div>", unsafe_allow_html=True)
        selected_month = st.selectbox(
            "Month", ["All"] + month_names, index=0,
            label_visibility="collapsed", key="ag_filter_month",
        )
        st.markdown("<div class='ag-filter-heading'>SERVICE TYPE</div>", unsafe_allow_html=True)
        selected_service = st.selectbox(
            "Service Type", ["All"] + service_values, index=0,
            label_visibility="collapsed", key="ag_filter_service",
        )
        st.markdown("<div class='ag-filter-heading'>LOCATION</div>", unsafe_allow_html=True)
        selected_location = st.selectbox(
            "Location", ["All"] + location_values, index=0,
            label_visibility="collapsed", key="ag_filter_location",
        )
        st.caption("Filters apply to all dashboard pages.")

    if selected_year != "All":
        filtered = filtered.loc[date_values.dt.year.astype("Int64").astype(str) == selected_year]
    if selected_month != "All":
        month_mask = pd.to_datetime(filtered["Date"], errors="coerce").dt.month == month_names.index(selected_month) + 1
        filtered = filtered.loc[month_mask]
    if selected_service != "All":
        filtered = filtered.loc[filtered["Service"].astype(str).str.strip() == selected_service]
    if selected_location != "All":
        filtered = filtered.loc[filtered["Location"].astype(str).str.strip() == selected_location]

    return filtered, {
        "year": selected_year,
        "month": selected_month,
        "service": selected_service,
        "location": selected_location,
    }


# -----------------------------------------------------------------------------
# Forecasting methods
# -----------------------------------------------------------------------------

def complete_monthly(series: pd.Series) -> pd.Series:
    series = series.copy().sort_index().astype(float)
    series.index = pd.to_datetime(series.index).to_period("M").to_timestamp()
    if series.empty:
        return series
    full_index = pd.date_range(series.index.min(), series.index.max(), freq="MS")
    return series.reindex(full_index, fill_value=0.0)


def forecast_method(train: pd.Series, method: str, horizon: int) -> np.ndarray:
    values = train.astype(float).to_numpy()
    if method == "Naive":
        return np.repeat(values[-1], horizon)
    if method == "Seasonal naive":
        if len(values) >= 12:
            seasonal = values[-12:]
        else:
            seasonal = values
        return np.array([seasonal[i % len(seasonal)] for i in range(horizon)], dtype=float)
    if method == "ETS" and ExponentialSmoothing is not None and len(values) >= 8:
        s = pd.Series(values)
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            if len(values) >= 24:
                model = ExponentialSmoothing(
                    s, trend="add", damped_trend=True, seasonal="add",
                    seasonal_periods=12, initialization_method="estimated"
                ).fit(optimized=True, remove_bias=True)
            else:
                model = ExponentialSmoothing(
                    s, trend="add", initialization_method="estimated"
                ).fit(optimized=True, remove_bias=True)
            pred = np.asarray(model.forecast(horizon), dtype=float)
        return np.maximum(pred, 0.0)
    raise ValueError(f"{method} cannot be fitted to this history.")


def backtest_forecasts(series: pd.Series, horizon: int = 3) -> tuple[pd.DataFrame, dict[str, np.ndarray]]:
    methods = ["Naive"]
    if len(series) >= 12:
        methods.append("Seasonal naive")
    if ExponentialSmoothing is not None and len(series) >= 8:
        methods.append("ETS")
    min_train = 24 if len(series) >= 36 else max(8, min(12, len(series) - horizon))
    errors: dict[str, list[float]] = {m: [] for m in methods}
    actuals: dict[str, list[float]] = {m: [] for m in methods}
    predictions: dict[str, list[float]] = {m: [] for m in methods}
    for end in range(min_train, len(series) - horizon + 1):
        train = series.iloc[:end]
        actual = series.iloc[end:end + horizon].to_numpy(dtype=float)
        for method in methods:
            try:
                pred = forecast_method(train, method, horizon)
                errors[method].extend((actual - pred).tolist())
                actuals[method].extend(actual.tolist())
                predictions[method].extend(pred.tolist())
            except Exception:
                continue
    rows = []
    residuals: dict[str, np.ndarray] = {}
    for method in methods:
        err = np.asarray(errors[method], dtype=float)
        act = np.asarray(actuals[method], dtype=float)
        pred = np.asarray(predictions[method], dtype=float)
        if len(err) == 0:
            continue
        mae = float(np.mean(np.abs(err)))
        denom = float(np.sum(np.abs(act)))
        wape = float(np.sum(np.abs(err)) / denom) if denom > 0 else np.nan
        bias = float(np.sum(pred - act) / denom) if denom > 0 else np.nan
        rows.append({"Model": method, "MAE (KES)": mae, "WAPE": wape, "Forecast bias": bias, "Backtest forecasts": len(err)})
        residuals[method] = err
    metrics = pd.DataFrame(rows).sort_values("WAPE", na_position="last") if rows else pd.DataFrame()
    return metrics, residuals


def create_monthly_forecast(series: pd.Series, horizon: int = 3) -> tuple[pd.DataFrame, pd.DataFrame, str, str]:
    series = complete_monthly(series)
    if len(series) < 6:
        raise ValueError("At least six monthly observations are required. Twelve or more are preferable; 24+ provide a stronger basis for annual seasonality.")
    metrics, residuals = backtest_forecasts(series, horizon)
    available = metrics["Model"].tolist() if not metrics.empty else ["Naive"]
    selected = available[0]
    pred = forecast_method(series, selected, horizon)
    future_idx = pd.date_range(series.index[-1] + pd.offsets.MonthBegin(1), periods=horizon, freq="MS")
    err = residuals.get(selected, np.array([], dtype=float))
    if len(err) >= 8:
        abs_q80 = float(np.quantile(np.abs(err), 0.80))
        abs_q95 = float(np.quantile(np.abs(err), 0.95))
    elif len(err):
        abs_q80 = abs_q95 = float(np.median(np.abs(err)))
    else:
        changes = series.diff().dropna().to_numpy(dtype=float)
        scale = float(np.std(changes, ddof=1)) if len(changes) > 1 else 0.0
        abs_q80, abs_q95 = 1.28 * scale, 1.96 * scale
    frame = pd.DataFrame({
        "Month": future_idx,
        "Forecast (KES)": np.maximum(pred, 0.0),
        "Lower 80% (KES)": np.maximum(pred - abs_q80, 0.0),
        "Upper 80% (KES)": np.maximum(pred + abs_q80, 0.0),
        "Lower 95% (KES)": np.maximum(pred - abs_q95, 0.0),
        "Upper 95% (KES)": np.maximum(pred + abs_q95, 0.0),
    })
    note = "Bands are empirical backtest-error ranges, not guaranteed prediction intervals."
    return frame, metrics, selected, note


