def show_hero(page_title: str, description: str) -> None:
    """Render one branded/page heading without repeating the business name."""
    st.markdown(
        f"""
        <div class="ag-hero">
          <span class="ag-hero-bubble" style="width:78px;height:78px;right:7%;top:-25px"></span>
          <span class="ag-hero-bubble" style="width:36px;height:36px;right:18%;bottom:-15px;animation-delay:-2s"></span>
          <span class="ag-hero-bubble" style="width:24px;height:24px;right:28%;top:14px;animation-delay:-4s"></span>
          <h1>{page_title}</h1>
          <p>{description}</p>
        </div>
        """,
        unsafe_allow_html=True,
    )


def show_page_heading(page_title: str, description: str) -> None:
    """Compact page title used beneath the single application brand header."""
    st.markdown(
        f"""
        <div class="ag-page-heading">
          <div class="ag-page-title">{page_title}</div>
          <div class="ag-page-description">{description}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def kpi_row(items: list[tuple[str, str, str | None]]) -> None:
    cols = st.columns(len(items))
    for col, (label, value, help_text) in zip(cols, items):
        col.metric(label, value, help=help_text)


def base_data_quality(meta: dict[str, Any]) -> None:
    q = meta["quality"]
    st.caption(
        f"Source sheet: {meta['jobs_sheet']} · {q['valid_jobs']:,} valid jobs · "
        f"{q['exact_duplicates_removed']:,} exact duplicate rows removed · "
        f"{q['conflicting_job_ids_excluded']:,} conflicting Job_IDs excluded"
    )


def page_overview(df: pd.DataFrame, meta: dict[str, Any]) -> None:
    show_page_heading("BUSINESS OVERVIEW", "A consolidated view of jobs, revenue, contribution and collections")
    base_data_quality(meta)
    jobs_n = df["Job_ID"].nunique()
    quote = df["Quoted"].sum()
    costs = df["Direct_Cost"].sum()
    contrib = quote - costs
    margin = contrib / quote if quote else np.nan
    collected = df["Collected"].sum()
    outstanding = df["Outstanding"].sum()
    kpi_row([
        ("TOTAL JOBS", f"{jobs_n:,}", None),
        ("QUOTED REVENUE", money(quote), None),
        ("DIRECT COST", money(costs), None),
        ("OVERALL CONTRIBUTION", money(contrib), None),
        ("CONTRIBUTION MARGIN", pct(margin), None),
    ])
    st.write("")
    kpi_row([
        ("AMOUNT COLLECTED", money(collected), None),
        ("OUTSTANDING BALANCE", money(outstanding), None),
        ("COLLECTION RATE", pct(collected / quote if quote else np.nan), "Collected divided by quoted revenue"),
        ("AVERAGE QUOTE PER JOB", money(df["Quoted"].mean() if len(df) else 0), None),
    ])

    section("Monthly business trend", "Quoted job value and recorded collections by month")
    temp = df.copy()
    temp["Month"] = temp["Date"].dt.to_period("M").dt.to_timestamp()
    revenue_monthly = temp.groupby("Month")["Quoted"].sum().rename("Quoted")
    tx = meta.get("collection_transactions", pd.DataFrame()).copy()
    if not tx.empty:
        tx = tx[tx["Job_ID"].astype(str).isin(df["Job_ID"].astype(str))].dropna(subset=["Date"]).copy()
        tx["Month"] = tx["Date"].dt.to_period("M").dt.to_timestamp()
        collection_monthly = tx.groupby("Month")["Amount"].sum().rename("Collections")
    else:
        collection_monthly = temp.groupby("Month")["Collected"].sum().rename("Collections")
    monthly = pd.concat([revenue_monthly, collection_monthly], axis=1).fillna(0)
    monthly.index.name = "Month"
    monthly = monthly.reset_index()
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=monthly["Month"], y=monthly["Quoted"], mode="lines+markers", name="Quoted revenue", line=dict(color=STEEL, width=3)))
    fig.add_trace(go.Scatter(x=monthly["Month"], y=monthly["Collections"], mode="lines+markers", name="Collections", line=dict(color=ORANGE, width=3)))
    fig.update_layout(title="Monthly quoted revenue and collections", yaxis_title="KES", xaxis_title="Month", hovermode="x unified")
    st.plotly_chart(chart_layout(fig, 370), use_container_width=True)

    left, right = st.columns([1, 1])
    with left:
        # Heading is rendered independently above the chart. A horizontal bar
        # chart uses service names as direct category labels, so a crowded
        # Plotly legend is unnecessary and cannot overlap the heading.
        section("Jobs by cleaning service", "Job count by service category")
        svc = df.groupby("Service").size().sort_values(ascending=True).reset_index(name="Jobs")
        fig2 = px.bar(
            svc, x="Jobs", y="Service", orientation="h",
            text="Jobs", color_discrete_sequence=[STEEL],
        )
        fig2.update_traces(
            texttemplate="%{x:,.0f}", textposition="outside",
            cliponaxis=False, marker_line_width=0,
        )
        fig2.update_layout(
            showlegend=False, xaxis_title="Number of jobs", yaxis_title="",
            uniformtext_minsize=9, uniformtext_mode="hide",
        )
        fig2.update_xaxes(rangemode="tozero", automargin=True)
        fig2.update_yaxes(automargin=True)
        st.plotly_chart(chart_layout(fig2, max(340, 32 * len(svc) + 90)), use_container_width=True)
    with right:
        section("Contribution by service", "Contribution after direct job costs")
        group = df.groupby("Service")["Contribution"].sum().sort_values().reset_index()
        fig3 = px.bar(group, x="Contribution", y="Service", orientation="h", color="Contribution", color_continuous_scale=[[0, CORAL], [.5, "#AABBC5"], [1, TEAL]])
        fig3.update_layout(coloraxis_showscale=False, xaxis_title="Contribution (KES)", yaxis_title="", showlegend=False)
        fig3.update_xaxes(automargin=True)
        fig3.update_yaxes(automargin=True)
        st.plotly_chart(chart_layout(fig3, max(340, 32 * len(group) + 90)), use_container_width=True)


def service_summary(df: pd.DataFrame) -> pd.DataFrame:
    g = df.groupby("Service").agg(
        Jobs=("Job_ID", "nunique"),
        Quoted_Revenue=("Quoted", "sum"),
        Labour_Cost=("Labour_Cost", "sum"),
        Material_Cost=("Material_Cost", "sum"),
        Staff_Support=("Staff_Support_Cost", "sum"),
        Direct_Cost=("Direct_Cost", "sum"),
        Contribution=("Contribution", "sum"),
        Collected=("Collected", "sum"),
        Outstanding=("Outstanding", "sum"),
    ).reset_index()
    g["Average_Quote"] = g["Quoted_Revenue"] / g["Jobs"].replace(0, np.nan)
    g["Average_Direct_Cost"] = g["Direct_Cost"] / g["Jobs"].replace(0, np.nan)
    g["Minimum_Quote_30"] = g["Average_Direct_Cost"] / (1 - TARGET_MARGIN)
    g["Quote_Gap"] = g["Average_Quote"] - g["Minimum_Quote_30"]
    g["Contribution_Margin"] = g["Contribution"] / g["Quoted_Revenue"].replace(0, np.nan)
    return g


def page_service(df: pd.DataFrame) -> None:
    show_page_heading("SERVICE PERFORMANCE", "Understand which cleaning services contribute most to the business")
    g = service_summary(df)
    jobs_n = g["Jobs"].sum()
    contribution = g["Contribution"].sum()
    below = int((g["Quote_Gap"] < 0).sum())
    kpi_row([
        ("SERVICE CATEGORIES", f"{len(g):,}", None),
        ("COMPLETED / INCLUDED JOBS", f"{jobs_n:,}", None),
        ("TOTAL CONTRIBUTION", money(contribution), None),
        ("SERVICES BELOW 30% TARGET", f"{below} of {len(g)}", "Based on average quote versus average direct cost at 30% target margin"),
    ])
    section("Contribution margin by service", "Bars extend left for negative margins and right for positive margins")
    margin_fig = px.bar(
        g.sort_values("Contribution_Margin"), x="Contribution_Margin", y="Service",
        orientation="h", color="Contribution_Margin",
        color_continuous_scale=[[0, CORAL], [.45, "#F2C2A8"], [.5, "#DCE8EE"], [.72, STEEL], [1, TEAL]],
        range_color=[min(-2, float(g["Contribution_Margin"].min(skipna=True) or 0)), max(.1, float(g["Contribution_Margin"].max(skipna=True) or 0))],
    )
    margin_fig.add_vline(x=0, line_color=NAVY, line_width=1)
    margin_fig.update_xaxes(tickformat=".0%", title="Contribution margin (%)")
    margin_fig.update_layout(yaxis_title="", coloraxis_showscale=False)
    st.plotly_chart(chart_layout(margin_fig, 440), use_container_width=True)

    section("Job volume and contribution")
    left, right = st.columns(2)
    with left:
        fig = px.bar(g.sort_values("Jobs", ascending=False), x="Service", y="Jobs", color_discrete_sequence=[STEEL], text="Jobs")
        fig.update_layout(xaxis_title="Service", yaxis_title="Number of jobs")
        fig.update_xaxes(tickangle=-25)
        st.plotly_chart(chart_layout(fig, 350), use_container_width=True)
    with right:
        fig = px.bar(g.sort_values("Contribution", ascending=False), x="Service", y="Contribution", color="Contribution", color_continuous_scale=[[0, CORAL], [.5, STEEL], [1, TEAL]])
        fig.update_layout(xaxis_title="Service", yaxis_title="Contribution (KES)", coloraxis_showscale=False)
        fig.update_xaxes(tickangle=-25)
        st.plotly_chart(chart_layout(fig, 350), use_container_width=True)

    display = g[["Service", "Jobs", "Quoted_Revenue", "Direct_Cost", "Contribution", "Contribution_Margin"]].copy()
    display.columns = ["Service", "Jobs", "Quoted revenue (KES)", "Direct cost (KES)", "Contribution (KES)", "Contribution margin"]
    display["Contribution margin"] = display["Contribution margin"].map(pct)
    for c in ["Quoted revenue (KES)", "Direct cost (KES)", "Contribution (KES)"]:
        display[c] = display[c].map(lambda v: f"{v:,.0f}")
    st.dataframe(display, hide_index=True, use_container_width=True)


def page_costs(df: pd.DataFrame, meta: dict[str, Any]) -> None:
    show_page_heading("COST & QUOTATION", "Assess direct job costs and benchmark quotations against a 30% target margin")
    labour = float(df["Labour_Cost"].sum())
    materials = float(df["Material_Cost"].sum())
    staff = float(df["Staff_Support_Cost"].sum())
    direct = labour + materials + staff
    contribution = float(df["Quoted"].sum() - direct)
    margin = contribution / df["Quoted"].sum() if df["Quoted"].sum() else np.nan
    kpi_row([
        ("AGREED LABOUR", money(labour), None),
        ("MATERIALS", money(materials), None),
        ("STAFF LUNCH & TRANSPORT", money(staff), None),
        ("TOTAL DIRECT COST", money(direct), None),
        ("OVERALL MARGIN", pct(margin), None),
    ])

    left, right = st.columns([.9, 1.1])
    with left:
        section("Direct cost composition")
        comp = pd.DataFrame({"Cost category": ["Agreed labour", "Materials", "Staff lunch & transport"], "Cost": [labour, materials, staff]})
        comp = comp[comp["Cost"] > 0]
        fig = px.bar(comp.sort_values("Cost"), x="Cost", y="Cost category", orientation="h", color="Cost category", color_discrete_map={"Agreed labour": TEAL, "Materials": STEEL, "Staff lunch & transport": ORANGE}, text=comp["Cost"].map(lambda v: f"KES {v:,.0f}"))
        fig.update_layout(showlegend=False, xaxis_title="Direct cost (KES)", yaxis_title="")
        st.plotly_chart(chart_layout(fig, 350), use_container_width=True)
    with right:
        section("Average quote vs minimum quote at 30% margin")
        g = service_summary(df).sort_values("Average_Quote", ascending=True)
        fig = go.Figure()
        fig.add_trace(go.Bar(y=g["Service"], x=g["Average_Quote"], name="Average quote", orientation="h", marker_color=STEEL))
        fig.add_trace(go.Bar(y=g["Service"], x=g["Minimum_Quote_30"], name="Minimum quote @ 30%", orientation="h", marker_color=TEAL))
        fig.update_layout(barmode="group", xaxis_title="Average quotation (KES)", yaxis_title="")
        st.plotly_chart(chart_layout(fig, 350), use_container_width=True)

    section("Service-level quotation check")
    g = service_summary(df).sort_values("Quote_Gap")
    out = g[["Service", "Jobs", "Average_Quote", "Average_Direct_Cost", "Minimum_Quote_30", "Quote_Gap"]].copy()
    out["Benchmark"] = np.where(out["Quote_Gap"] >= 0, "At / above target", "Below target")
    out.columns = ["Service", "Jobs", "Average quote (KES)", "Average direct cost (KES)", "Minimum quote @ 30% (KES)", "Quote gap (KES)", "Benchmark"]
    st.dataframe(out.style.format({c: "{:,.0f}" for c in out.columns if "KES" in c}), hide_index=True, use_container_width=True)
    st.markdown(
        "<div class='ag-note'>Minimum quotation = average direct cost ÷ (1 − 30%). "
        "This is a contribution-margin benchmark, not a net-profit target. General business expenditure "
        "is kept separate from direct job costs.</div>",
        unsafe_allow_html=True,
    )
    if meta.get("overhead_total", 0) > 0:
        with st.expander("General business expenditure (shown separately)"):
            st.metric("Recorded general business expenditure", money(meta["overhead_total"]))
            if not meta["overhead_by_type"].empty:
                st.dataframe(meta["overhead_by_type"].style.format({"Amount": "{:,.0f}"}), hide_index=True, use_container_width=True)


def page_collections(df: pd.DataFrame, meta: dict[str, Any]) -> None:
    show_page_heading("PAYMENT & COLLECTION", "Monitor received amounts, outstanding balances and collection outcomes")
    quote = float(df["Quoted"].sum())
    collected = float(df["Collected"].sum())
    outstanding = float(df["Outstanding"].sum())
    rate = collected / quote if quote > 0 else np.nan
    full = int((df["Collection_Outcome"] == "Paid in full").sum())
    partial = int((df["Collection_Outcome"] == "Partially paid").sum())
    unpaid = int((df["Collection_Outcome"] == "Unpaid").sum())
    kpi_row([
        ("AMOUNT COLLECTED", money(collected), None),
        ("OUTSTANDING BALANCE", money(outstanding), None),
        ("COLLECTION RATE", pct(rate), "Amount collected divided by quoted revenue"),
        ("JOBS PAID IN FULL", f"{full:,} / {len(df):,}", None),
    ])
    left, right = st.columns(2)
    with left:
        # A labelled horizontal bar chart is clearer than a donut for a small
        # set of discrete payment outcomes, especially on narrow screens.
        section("Collection outcome", "Jobs grouped by payment status")
        outcome = pd.DataFrame({"Outcome": ["Paid in full", "Partially paid", "Unpaid"], "Jobs": [full, partial, unpaid]})
        outcome = outcome[outcome["Jobs"] > 0].sort_values("Jobs", ascending=True)
        outcome_colors = {"Paid in full": GREEN, "Partially paid": ORANGE, "Unpaid": CORAL}
        fig = px.bar(
            outcome, x="Jobs", y="Outcome", orientation="h",
            color="Outcome", color_discrete_map=outcome_colors, text="Jobs",
            category_orders={"Outcome": outcome["Outcome"].tolist()},
        )
        fig.update_traces(texttemplate="%{x:,.0f}", textposition="outside", cliponaxis=False)
        fig.update_layout(showlegend=False, xaxis_title="Number of jobs", yaxis_title="")
        fig.update_xaxes(rangemode="tozero", automargin=True)
        fig.update_yaxes(automargin=True)
        st.plotly_chart(chart_layout(fig, 370), use_container_width=True)
    with right:
        section("Outstanding balance by service")
        by_service = df.groupby("Service")["Outstanding"].sum().sort_values().reset_index()
        fig = px.bar(by_service, x="Outstanding", y="Service", orientation="h", color_discrete_sequence=[CORAL], text=by_service["Outstanding"].map(lambda v: f"{v/1_000_000:.2f}M" if v >= 1_000_000 else f"{v:,.0f}"))
        fig.update_layout(xaxis_title="Outstanding balance (KES)", yaxis_title="")
        st.plotly_chart(chart_layout(fig, 370), use_container_width=True)

    section("Collection summary by service")
    g = df.groupby("Service").agg(Jobs=("Job_ID", "nunique"), Quoted=("Quoted", "sum"), Collected=("Collected", "sum"), Outstanding=("Outstanding", "sum")).reset_index()
    g["Collection rate"] = g["Collected"] / g["Quoted"].replace(0, np.nan)
    g["Collection rate"] = g["Collection rate"].map(pct)
    g.columns = ["Service", "Jobs", "Quoted (KES)", "Collected (KES)", "Outstanding (KES)", "Collection rate"]
    st.dataframe(g.style.format({c: "{:,.0f}" for c in g.columns if "KES" in c}), hide_index=True, use_container_width=True)
    if meta.get("collection_date_proxy"):
        st.warning(
            "Monthly collection timing is estimated using job completion/job dates as there are no "
            "separate dated payment records. The overall collection totals "
            "are useful, but monthly cash timing should be interpreted as a proxy."
        )


def page_forecast(df: pd.DataFrame, meta: dict[str, Any]) -> None:
    show_page_heading("MONTHLY COLLECTIONS FORECAST", "Historical monthly collections and a rolling three-month outlook")
    if df["Collection_Date"].notna().sum() == 0:
        st.error("No usable date field was found for monthly collections. Add a Collection_Date, Completion_Date or Job_Date column.")
        return
    tx = meta.get("collection_transactions", pd.DataFrame()).copy()
    if not tx.empty:
        tx = tx[tx["Job_ID"].astype(str).isin(df["Job_ID"].astype(str))].copy()
        tx = tx.dropna(subset=["Date"])
        tx["Month"] = tx["Date"].dt.to_period("M").dt.to_timestamp()
        monthly = tx.groupby("Month")["Amount"].sum().sort_index()
    else:
        dated = df.dropna(subset=["Collection_Date"]).copy()
        dated["Month"] = dated["Collection_Date"].dt.to_period("M").dt.to_timestamp()
        monthly = dated.groupby("Month")["Collected"].sum().sort_index()
    monthly = complete_monthly(monthly)
    if monthly.sum() <= 0:
        st.error("No positive collection amounts were found in the selected workbook. Check that the job sheet contains Deposit and Balance Rec (or that a Payments sheet contains Received_Amount_KES).")
        return
    if len(monthly) < 6:
        st.error("There are fewer than six monthly observations. Add more dated operating records before forecasting.")
        return
    try:
        forecast, metrics, selected_model, band_note = create_monthly_forecast(monthly, FORECAST_HORIZON)
    except Exception as exc:
        st.error(f"The forecast could not be generated: {exc}")
        return

    forecast_total = float(forecast["Forecast (KES)"].sum())
    last_month = monthly.index[-1]
    kpi_row([
        ("HISTORICAL COLLECTIONS", money(monthly.sum()), f"{len(monthly):,} monthly observations"),
        ("AVERAGE MONTHLY COLLECTIONS", money(monthly.mean()), None),
        ("LATEST RECORDED MONTH", money(monthly.iloc[-1]), last_month.strftime("%B %Y")),
        ("NEXT 3-MONTH FORECAST", money(forecast_total), f"Selected model: {selected_model}"),
    ])
    if meta.get("collection_date_proxy"):
        st.warning("The forecast assigns deposit plus balance received to the job completion date (or job date). It therefore forecasts collections by job-month proxy, not the exact month cash entered the business.")

    section("Actual monthly collections and forecast", "Dashed line is the selected model. Shaded bands summarise historical backtest errors.")
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=monthly.index, y=monthly.values, mode="lines+markers", name="Historical collections", line=dict(color=STEEL, width=3)))
    fig.add_trace(go.Scatter(x=forecast["Month"], y=forecast["Upper 95% (KES)"], mode="lines", line=dict(width=0), showlegend=False, hoverinfo="skip"))
    fig.add_trace(go.Scatter(x=forecast["Month"], y=forecast["Lower 95% (KES)"], mode="lines", line=dict(width=0), fill="tonexty", fillcolor="rgba(82,127,159,.10)", name="Indicative 95% error band", hoverinfo="skip"))
    fig.add_trace(go.Scatter(x=forecast["Month"], y=forecast["Upper 80% (KES)"], mode="lines", line=dict(width=0), showlegend=False, hoverinfo="skip"))
    fig.add_trace(go.Scatter(x=forecast["Month"], y=forecast["Lower 80% (KES)"], mode="lines", line=dict(width=0), fill="tonexty", fillcolor="rgba(64,151,143,.17)", name="Indicative 80% error band", hoverinfo="skip"))
    fig.add_trace(go.Scatter(x=forecast["Month"], y=forecast["Forecast (KES)"], mode="lines+markers", name=f"Forecast — {selected_model}", line=dict(color=TEAL, width=3, dash="dash")))
    fig.add_vline(x=last_month, line_dash="dot", line_color=MUTED)
    fig.update_layout(xaxis_title="Month", yaxis_title="Collections (KES)", hovermode="x unified")
    st.plotly_chart(chart_layout(fig, 430), use_container_width=True)

    left, right = st.columns([1.15, .85])
    with left:
        section("Three-month collections outlook")
        view = forecast.copy()
        view["Month"] = view["Month"].dt.strftime("%B %Y")
        st.dataframe(view.style.format({c: "KES {:,.0f}" for c in view.columns if "KES" in c}), hide_index=True, use_container_width=True)
    with right:
        section("Forecast model comparison")
        if metrics.empty:
            st.info("Not enough backtest folds to compare models. The naive baseline is used.")
        else:
            m = metrics.copy()
            m["WAPE"] = m["WAPE"].map(lambda v: "—" if pd.isna(v) else f"{v:.1%}")
            m["Forecast bias"] = m["Forecast bias"].map(lambda v: "—" if pd.isna(v) else f"{v:+.1%}")
            m["MAE (KES)"] = m["MAE (KES)"].map(lambda v: money(v))
            st.dataframe(m, hide_index=True, use_container_width=True)
    st.markdown(f"<div class='ag-note'>{band_note} Model selection is based on rolling-origin WAPE; historical accuracy does not guarantee future performance.</div>", unsafe_allow_html=True)

    with st.expander("Forecast data and methodology"):
        st.write(f"Collection date basis: {meta['collection_date_basis']}")
        st.write(f"Monthly period: {monthly.index.min():%B %Y} to {monthly.index.max():%B %Y}")
        st.write(f"Monthly observations: {len(monthly)}")
        st.write(f"Selected model: {selected_model}")
        st.write("Models compared: Naive, Seasonal naive and ETS (where the history is long enough).")
        st.write("Validation: expanding-window rolling-origin backtesting using three-month forecast windows.")
        st.write("Error measures: MAE, WAPE and forecast bias.")


def app_main() -> None:
    # Keep the sidebar focused on the workbook and the four global slicers.
    # Dashboard navigation is moved into the main canvas so it cannot push
    # Month, Service Type and Location below the visible sidebar area.
    uploaded = None
    with st.sidebar:
        with st.expander("Change Excel workbook (optional)", expanded=False):
            uploaded = st.file_uploader(
                "Upload your Excel workbook",
                type=["xlsx"],
                help="Upload your single workbook containing Customers, Labour_Payments, Material_Usage, Lunch and transport, and General Business Expenditure.",
            )

    workbook_bytes: bytes | None = uploaded.getvalue() if uploaded is not None else None
    if workbook_bytes is None and DEFAULT_WORKBOOK.exists():
        workbook_bytes = DEFAULT_WORKBOOK.read_bytes()

    if workbook_bytes is None:
        show_hero("BUSINESS ANALYTICS", "Upload your workbook to view the dashboards")
        st.info("Upload your single Excel workbook in the left sidebar. The workbook should contain the job/customer sheet and the supporting labour, material, staff expense and general expenditure sheets.")
        st.stop()

    try:
        sheets = read_workbook(workbook_bytes)
        jobs, meta = load_business_model(sheets)
    except Exception as exc:
        show_hero("BUSINESS ANALYTICS", "Workbook could not be loaded")
        st.error(f"Unable to prepare the workbook: {exc}")
        with st.expander("Workbook sheets and column names"):
            for name, frame in read_workbook(workbook_bytes).items():
                st.write(name, list(frame.columns))
        st.stop()

    # Render all slicers before the page selector. This keeps them visible
    # together in the left panel rather than hiding them below navigation.
    filtered, filters = apply_global_filters(jobs)

    show_hero(
        "AMAZING GRACE CLEANING SERVICES",
        "Business performance · Service profitability · Quotation decisions · Cash collections",
    )
    page = st.radio(
        "DASHBOARD NAVIGATION",
        ["Business Overview", "Service Performance", "Cost & Quotation", "Payment & Collection", "Monthly Forecast"],
        horizontal=True,
        label_visibility="collapsed",
        key="ag_dashboard_page",
    )

    if filtered.empty:
        st.warning("No jobs match the selected filters. Change Year, Month, Service Type or Location in the left panel.")
        st.stop()

    if page == "Business Overview":
        page_overview(filtered, meta)
    elif page == "Service Performance":
        page_service(filtered)
    elif page == "Cost & Quotation":
        page_costs(filtered, meta)
    elif page == "Payment & Collection":
        page_collections(filtered, meta)
    else:
        # Forecast page uses the date-filtered job subset. Service and location
        # slicers are intentionally respected for a coherent filtered outlook.
        page_forecast(filtered, meta)

    st.markdown(
        "<div class='ag-footer'>Amazing Grace Cleaning Services · Internal business dashboard · "
        "Forecasts are estimates and should be reviewed against actual results.</div>",
        unsafe_allow_html=True,
    )


if __name__ == "__main__":
    app_main()
